#!/usr/bin/env bash
# percentEncode / percentDecode (abla/text), base64DecodeOrNull / hexDecodeOrNull (abla/crypto) and
# HttpRequest.queryParameterDecoded (abla/http), with Node as the oracle (tests/cases/percent-base64):
#  - cases.ab (generated by gen.mjs, checked here so they cannot drift): 1248 results that must equal what Node gives for
#    the same inputs (encodeURIComponent plus the characters RFC 3986 also escapes, decodeURIComponent which throws for a bad
#    escape or invalid UTF-8, a strict RFC 4648 check for Base64, a hex check), recorded in cases.expected so that the test
#    also runs without node; every case runs as ordinary code and under `#` in the interpreter and (ABLA_COMPILE_EVAL=jit)
#    the JIT tier, and the two must agree.
#  - query.ab: queryParameterDecoded on hand-checked queries (recorded in query.expected).
set -euo pipefail

compiler=${1:-build/ablac}
[[ $compiler == /* || $compiler != */* ]] || compiler="$PWD/$compiler"
project_root=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
cd "$project_root"
cases=tests/cases/percent-base64
out=build/percent-base64
rm -rf "$out"
mkdir -p "$out"

for name in cases query; do
    for tier in interp jit; do
        ABLA_COMPILE_EVAL=$tier "$compiler" build "$cases/$name.ab" -o "$out/$name-$tier" --fast --no-cache
        set +e
        "$out/$name-$tier" > "$out/$name-$tier.txt" 2>&1
        status=$?
        set -e
        [[ $status -eq 0 ]] || { echo "percent/base64: $name ($tier): run time and compile time differ:" >&2; grep -a '^DIFF' "$out/$name-$tier.txt" | head -10 >&2; exit 1; }
        if ! cmp -s "$cases/$name.expected" "$out/$name-$tier.txt"; then
            echo "percent/base64: $name ($tier) differs from $name.expected:" >&2
            diff "$cases/$name.expected" "$out/$name-$tier.txt" | head -20 >&2
            exit 1
        fi
    done
    sed '1s/.*/mutated/' "$cases/$name.expected" > "$out/mutated.expected"
    ! cmp -s "$out/mutated.expected" "$out/$name-interp.txt" || { echo "percent/base64: the negative control matched in $name" >&2; exit 1; }
done

node=${PERCENT_BASE64_NODE:-$(command -v node || true)}
if [[ -z $node ]]; then
    echo "percent/base64: recorded results match; the comparison with Node is skipped (no node)"
    exit 0
fi
"$node" "$cases/gen.mjs" "$out/cases.ab" "$out/node.txt"
cmp -s "$out/cases.ab" "$cases/cases.ab" || { echo "percent/base64: cases.ab is not what gen.mjs makes" >&2; exit 1; }
cmp -s "$out/node.txt" "$cases/cases.expected" || { echo "percent/base64: Node's results differ from cases.expected:" >&2; diff "$out/node.txt" "$cases/cases.expected" | head -20 >&2; exit 1; }
echo "percent/base64: $(wc -l < "$cases/cases.expected" | tr -d ' ') results equal Node's and agree at run time and under # (interpreter and JIT); queryParameterDecoded checked"
